//! Connected initial blank child events use their own native Document/Window path.
use super::*;
fn run(d:&mut Document,f:&mut Forms,p:&mut Page,s:&str)->Value{p.begin_job();p.runtime.execute(s,&mut Bridge{doc:d,forms:f,state:&mut p.state}).unwrap()}
fn fixture()->(Document,Forms,Page){let mut d=crate::html::parse_loaded_document("<!doctype html><html><body><div id=main>Main</div></body></html>",&||Ok(())).unwrap();d.scripting_enabled=true;let mut f=Forms::new(&d);let mut p=Page::new();p.set_location(&crate::navigation::address("https://child-event.test/source",&crate::navigation::Location::home()).unwrap());assert_eq!(p.start(&mut d,&mut f,&[]).errors,0);run(&mut d,&mut f,&mut p,"var frame=document.createElement('iframe');frame.hidden=true;document.body.appendChild(frame);var child=frame.contentWindow,owner=child.document,root=owner.documentElement,target=owner.body,add=child.EventTarget.prototype.addEventListener,dispatch=child.EventTarget.prototype.dispatchEvent,ChildCustom=child.CustomEvent,event=new ChildCustom('check',{bubbles:true,cancelable:true,composed:true,detail:{held:target}}),calls=0;function callback(){calls++;}document.body;");(d,f,p)}
#[test]
fn event_child_paths_actual_child_capture_target_bubble_cancel_and_no_embedding_bridge(){
 let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"
var expected=[target,root,owner,child],log='',outside=0;for(var node of [window,document,frame])node.addEventListener('check',function(){outside++;},true);function listen(node,tag,capture){add.call(node,'check',function(e){var path=e.composedPath();if(path.length!==4||e.target!==target||e.srcElement!==target||e.currentTarget!==node||e.detail.held!==target||e.isTrusted)throw 'actual child event values';for(var i=0;i<4;i++)if(path[i]!==expected[i])throw 'actual child path identity';path[0]=window;if(e.composedPath()[0]!==target)throw 'fresh child path array';log+=tag+e.eventPhase;},capture);}listen(child,'W',true);listen(owner,'D',true);listen(root,'H',true);listen(target,'C',true);listen(target,'T',false);listen(root,'H',false);listen(owner,'D',false);listen(child,'W',false);target.addEventListener('check',function(e){e.preventDefault();});if(target.dispatchEvent(event)!==false||log!=='W1D1H1C2T2H3D3W3'||outside||!event.defaultPrevented||event.target!==target||event.currentTarget!==null||event.eventPhase||event.composedPath().length)throw 'child native propagation and cleanup';
"#);assert!(p.state.synthetic_dispatches.is_empty());assert!(p.state.created_events.iter().all(|e|!e.dispatching));}
#[test]
fn event_child_paths_window_document_head_load_and_noncapture_boundaries(){
 let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"
var seen='',outside=0;for(var node of [window,document,frame])node.addEventListener('probe',function(){outside++;},true);function probe(node,type,expected){var count=0;add.call(node,type,function(e){var path=e.composedPath();if(path.length!==expected.length||e.target!==node||e.currentTarget!==node||e.eventPhase!==2||e.isTrusted)throw 'child root target fields';for(var i=0;i<path.length;i++)if(path[i]!==expected[i])throw 'child root exact path';count++;},{once:true});if(!dispatch.call(node,new Event(type,{bubbles:true}))||count!==1||outside)throw 'child root boundary';}probe(child,'probe',[child]);probe(owner,'probe',[owner,child]);probe(owner.head,'probe',[owner.head,root,owner,child]);probe(owner,'load',[owner]);probe(owner.head,'load',[owner.head,root,owner]);add.call(child,'quiet',function(e){seen+='W';},true);add.call(owner,'quiet',function(){seen+='D';},true);add.call(root,'quiet',function(){seen+='H';},true);add.call(target,'quiet',function(){seen+='T';});add.call(root,'quiet',function(){seen+='X';});dispatch.call(target,new Event('quiet'));if(seen!=='WDHT')throw 'nonbubbling child still captures';
"#);}
#[test]
fn event_child_paths_nested_listener_objects_abort_removal_and_invalid_event_reentry(){
 let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"
var log='',c=new AbortController(),listener={handleEvent:function(e){if(this!==listener||e.currentTarget!==root)throw 'child callback object receiver';log+='O';}};root.addEventListener('check',listener,{once:true});target.addEventListener('check',function(e){var denied=false;try{dispatch.call(target,e);}catch(error){denied=error.name==='InvalidStateError';}if(!denied)throw 'same child event reentry';c.abort();dispatch.call(owner,new Event('inner',{bubbles:true}));log+='T';},{once:true});add.call(child,'inner',function(){log+='I';});root.addEventListener('check',function(){log+='X';},{signal:c.signal});if(!dispatch.call(target,event)||log!=='ITO')throw 'actual nested child event and removed snapshot';dispatch.call(target,event);if(log!=='ITO')throw 'once child listeners removed';
"#);assert!(p.state.synthetic_dispatches.is_empty());}
#[test]
fn event_child_paths_saved_method_event_owner_and_disconnected_target_refusals_recover(){
 let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,"document.getElementById('main').addEventListener('check',callback);add.call(target,'check',callback);var savedTarget=target,bound=dispatch.bind(target),mainDispatch=EventTarget.prototype.dispatchEvent;");let count=p.state.listeners.len();p.set_location(&crate::navigation::address("https://other.test/source",&crate::navigation::Location::home()).unwrap());for source in ["mainDispatch.call(document.getElementById('main'),event)","dispatch.call(document.getElementById('main'),new Event('check'))","bound(event)","mainDispatch.call(savedTarget,new Event('check'))"]{p.begin_job();let error=p.runtime.execute(source,&mut Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}).unwrap_err();assert!(error.contains("origin"),"{error}");assert_eq!(p.state.listeners.len(),count);assert!(p.state.synthetic_dispatches.is_empty());}p.set_location(&crate::navigation::address("https://child-event.test/source",&crate::navigation::Location::home()).unwrap());run(&mut d,&mut f,&mut p,"if(calls)throw 'origin refusal callback prefix';mainDispatch.call(target,event);if(calls!==1)throw 'genuine child authority recovery';frame.remove();");let before=(p.state.retained,p.state.dom_commits);p.begin_job();let error=p.runtime.execute("bound(event)",&mut Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}).unwrap_err();assert!(error.contains("teardown")||error.contains("connected"),"{error}");assert_eq!((p.state.retained,p.state.dom_commits),before);assert!(p.state.synthetic_dispatches.is_empty());run(&mut d,&mut f,&mut p,"var fresh=document.createElement('iframe');fresh.hidden=true;document.body.appendChild(fresh);var freshTarget=fresh.contentWindow.document.body;if(freshTarget===savedTarget)throw 'fresh real child identity';freshTarget.addEventListener('check',callback);mainDispatch.call(freshTarget,new Event('check'));if(calls!==2)throw 'fresh connected child recovery';");}
#[test]
fn event_child_paths_work_copy_retained_deadline_refuse_without_dispatch_prefix_and_recover(){
 for profile in 0..4{let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,"add.call(target,'check',callback);");let before=(p.state.retained,p.state.dom_commits);let limit=p.state.retained_limit;p.begin_job();match profile{0=>p.state.host_work=0,1=>p.state.copy_work=0,2=>p.state.retained_limit=p.state.retained,_=>p.state.execution_deadline=Some(Instant::now())}assert!(p.runtime.execute("dispatch.call(target,event)",&mut Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}).is_err());assert_eq!((p.state.retained,p.state.dom_commits),before);assert!(p.state.synthetic_dispatches.is_empty());assert!(p.state.created_events.iter().all(|e|!e.dispatching));p.state.retained_limit=limit;run(&mut d,&mut f,&mut p,"if(calls||event.currentTarget!==null||event.eventPhase||event.composedPath().length)throw 'child dispatch refusal prefix';if(!dispatch.call(target,event)||calls!==1)throw 'fresh child dispatch recovery';");}
}
